<script setup lang="ts">defineProps<{modelValue?:string|number;options:{id:string;label:string}[]}>();const emit=defineEmits<{ 'update:modelValue':[value:any] }>();</script><template><picker :range="options" range-key="label" :value="Math.max(0,options.findIndex(o=>o.id===String(modelValue)))" @change="emit('update:modelValue',options[Number($event.detail.value)]?.id)"><view class="choice">{{options.find(o=>o.id===String(modelValue))?.label||'请选择'}} <text>⌄</text></view></picker></template><style scoped>.choice{display:flex;justify-content:space-between;gap:8px;background:var(--studio-input,#172329);border:1px solid var(--studio-border,#ffffff12);padding:11px 12px;border-radius:6px;color:var(--studio-text,#d8e3df);font-size:12px;min-height:39px;box-sizing:border-box}</style>